insert into public.club_competitions (
  id_club_competition,
  nom,
  date,
  categorie_age,
  niveau
)
select
  id_club_competition,
  nom,
  date::date,
  categorie_age,
  niveau
from seed_rows
on conflict (id_club_competition) do update set
  nom = excluded.nom,
  date = excluded.date,
  categorie_age = excluded.categorie_age,
  niveau = excluded.niveau,
  updated_at = now();

